const products=[{name:'Solana Beach',slug:'solana-beach',region:'San Diego'},{name:'Oceanside',slug:'oceanside',region:'San Diego'},{name:'Cabrillo',slug:'cabrillo',region:'San Diego'},{name:'Newport',slug:'newport',region:'Orange County'},{name:'Redondo',slug:'redondo',region:'Los Angeles'},{name:'San Clemente',slug:'san-clemente',region:'Orange County'},{name:'Riverside',slug:'riverside',region:'Inland'},{name:'Dana Point',slug:'dana-point',region:'Orange County'},{name:'Del Mar',slug:'del-mar',region:'San Diego'},{name:'Laguna Beach',slug:'laguna-beach',region:'Orange County'},{name:'La Jolla',slug:'la-jolla',region:'San Diego'},{name:'Carlsbad',slug:'carlsbad',region:'San Diego'},{name:'Encinitas',slug:'encinitas',region:'San Diego'},{name:'Cardiff',slug:'cardiff',region:'San Diego'},{name:'Torrey Pines',slug:'torrey-pines',region:'San Diego'}];
const $=s=>document.querySelector(s);let region='All',selected,picks=[];try{const saved=JSON.parse(localStorage.getItem('califrames-picks')||'[]');if(Array.isArray(saved))picks=saved.filter(x=>products.some(p=>p.slug===x.slug)&&['Oak frame','Black frame','White frame','Unframed print'].includes(x.frame))}catch{};
function render(){const q=$('#search').value.trim().toLowerCase();const shown=products.filter(p=>(region==='All'||p.region===region)&&p.name.toLowerCase().includes(q));$('#grid').innerHTML=shown.map(p=>`<button class="card" data-slug="${p.slug}" aria-label="View ${p.name} poster"><div class="card-art"><img src="assets/${p.slug}-hq.webp" alt="${p.name} illustrated California poster" loading="lazy" width="1448" height="2048"></div><div class="card-title">${p.name}<span aria-hidden="true">↗</span></div><small>${p.region} · California city series</small></button>`).join('');$('#result-count').textContent=`${shown.length} ${shown.length===1?'place':'places'} to love`;$('#empty').hidden=shown.length>0}
$('.filters').addEventListener('click',e=>{if(!e.target.matches('button'))return;region=e.target.dataset.region;document.querySelectorAll('.filters button').forEach(b=>b.classList.toggle('active',b===e.target));render()});$('#search').addEventListener('input',render);
$('#grid').addEventListener('click',e=>{const c=e.target.closest('.card');if(!c)return;selected=products.find(p=>p.slug===c.dataset.slug);$('#product-title').textContent=selected.name;$('#product-region').textContent=selected.region+' · CALIFORNIA';$('#product-description').textContent=`A little ${selected.name}, for wherever you call home. Part of our colorful California city poster collection.`;$('#product-img').src=`assets/${selected.slug}-hq.webp`;$('#product-img').alt=selected.name+' poster artwork preview';$('#frame').value='Oak frame';$('#product').showModal()});
function update(){ $('#count').textContent=picks.length;try{localStorage.setItem('califrames-picks',JSON.stringify(picks))}catch{} }
$('#add').addEventListener('click',()=>{picks.push({slug:selected.slug,frame:$('#frame').value});update();$('#product').close();$('#toast').textContent=selected.name+' added to your picks';$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2500)});
function renderBag(){const root=$('#bag-items');root.replaceChildren();if(!picks.length){const p=document.createElement('p');p.textContent='Your next happy place is waiting. Explore the collection and add a city you love.';root.append(p)}picks.forEach((item,i)=>{const p=products.find(p=>p.slug===item.slug),row=document.createElement('div');row.innerHTML=`<img src="assets/${p.slug}-hq.webp" alt="${p.name} poster"><p>${p.name}<small>${item.frame}</small></p><button data-remove="${i}" aria-label="Remove ${p.name}">Remove</button>`;root.append(row)});$('#email-order').hidden=!picks.length;const body='Hi Califrames! I’m interested in these posters:\n\n'+picks.map(x=>products.find(p=>p.slug===x.slug).name+' — '+x.frame).join('\n')+'\n\nPlease send me available sizes, pricing, and pickup or delivery options.\n\nThank you!';$('#email-order').href='mailto:hello@califrames.com?subject='+encodeURIComponent('My Califrames poster selection')+'&body='+encodeURIComponent(body)}
$('#open-bag').addEventListener('click',()=>{renderBag();$('#bag').showModal()});$('#bag-items').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(!b)return;picks.splice(Number(b.dataset.remove),1);update();renderBag()});$('#keep-shopping').addEventListener('click',()=>{$('#bag').close();$('#collection').scrollIntoView({behavior:'smooth'})});document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});render();update();
